using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _service;

    public OrderServiceTests()
    {
        _service = new OrderService();
    }

    private static List<OrderItem> CreateItems(int count = 1) =>
        Enumerable.Range(1, count)
            .Select(i => new OrderItem { ProductName = $"Product{i}", Price = 10m * i, Quantity = i })
            .ToList();

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectTotal()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "Widget", Price = 25m, Quantity = 2 },
            new() { ProductName = "Gadget", Price = 15m, Quantity = 1 },
        };

        // Act
        var order = _service.CreateOrder("customer-1", items);

        // Assert
        Assert.AreEqual(65m, order.Total); // 25*2 + 15*1
        Assert.AreEqual("customer-1", order.CustomerId);
        Assert.IsNotNull(order.Id);
        Assert.HasCount(2, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithNullCustomerId_ThrowsArgumentNullException()
    {
        var items = CreateItems();

        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _service.CreateOrder(null!, items));
        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithNullItems_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _service.CreateOrder("cust-1", null!));
        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _service.CreateOrder("cust-1", []));
        Assert.Contains("no items", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    [TestMethod]
    public void GetOrder_WithExistingId_ReturnsOrder()
    {
        // Arrange
        var created = _service.CreateOrder("cust-1", CreateItems());

        // Act
        var found = _service.GetOrder(created.Id);

        // Assert
        Assert.AreSame(created, found);
    }

    [TestMethod]
    public void GetOrder_WithNonExistentId_ReturnsNull()
    {
        var result = _service.GetOrder("non-existent");

        Assert.IsNull(result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_ReturnsOnlyMatchingOrders()
    {
        // Arrange
        _service.CreateOrder("cust-1", CreateItems());
        _service.CreateOrder("cust-1", CreateItems(2));
        _service.CreateOrder("cust-2", CreateItems());

        // Act
        var orders = _service.GetOrdersByCustomer("cust-1");

        // Assert
        Assert.HasCount(2, orders);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithNoOrders_ReturnsEmptyList()
    {
        var orders = _service.GetOrdersByCustomer("unknown");

        Assert.IsEmpty(orders);
    }

    [TestMethod]
    [DataRow(1, 10)]    // 10 * 1
    [DataRow(3, 60)]    // 10*1 + 20*2 + ... simplified: sum(10i * i) for i=1..3 = 10+40+90 = 140... let me recalculate
    public void CreateOrder_WithVariousItemCounts_CalculatesTotalCorrectly(int itemCount, decimal expectedTotal)
    {
        // CreateItems produces items where item i has Price=10*i, Quantity=i
        // So total = sum(10*i * i) for i = 1..itemCount
        var items = Enumerable.Range(1, itemCount)
            .Select(i => new OrderItem { ProductName = $"P{i}", Price = 10m, Quantity = i })
            .ToList();
        // total = 10 * sum(i) for i=1..itemCount = 10 * itemCount*(itemCount+1)/2

        var order = _service.CreateOrder("cust-1", items);

        Assert.AreEqual(expectedTotal, order.Total);
    }
}

